window.GEOMETRY_DIAGNOSTIC=[{"id":"geo-d-01","unit":1,"skill":"Points, Lines, Planes & Defined Terms","prompt":"Two complementary angles measure 62° and y°. Find y.","options":["46","A straight angle","A postulate is accepted without proof; a theorem is proven","28"],"answer":3,"answer_text":"28","explanation":"Complementary angles sum to 90°, so y=90−62."},{"id":"geo-d-02","unit":1,"skill":"Points, Lines, Planes & Defined Terms","prompt":"Two supplementary angles measure 134° and y°. Find y.","options":["28","A straight angle","46","A postulate is accepted without proof; a theorem is proven"],"answer":2,"answer_text":"46","explanation":"Supplementary angles sum to 180°, so y=180−134."},{"id":"geo-d-03","unit":1,"skill":"Points, Lines, Planes & Defined Terms","prompt":"Name the angle formed by opposite rays.","options":["A straight angle","28","46","A postulate is accepted without proof; a theorem is proven"],"answer":0,"answer_text":"A straight angle","explanation":"Opposite rays form a 180° angle."},{"id":"geo-d-04","unit":1,"skill":"Points, Lines, Planes & Defined Terms","prompt":"What is the difference between a postulate and a theorem?","options":["28","46","A postulate is accepted without proof; a theorem is proven","A straight angle"],"answer":2,"answer_text":"A postulate is accepted without proof; a theorem is proven","explanation":"Both may be used as reasons once established."},{"id":"geo-d-05","unit":1,"skill":"Points, Lines, Planes & Defined Terms","prompt":"In a two-column proof, what belongs in the right column?","options":["Reasons that justify each statement","46","28","A straight angle"],"answer":0,"answer_text":"Reasons that justify each statement","explanation":"Each step must cite a definition, property, postulate, or theorem."},{"id":"geo-d-06","unit":1,"skill":"Points, Lines, Planes & Defined Terms","prompt":"Why is a diagram alone not sufficient proof?","options":["28","A straight angle","It may not be drawn to scale and cannot establish every required relationship","46"],"answer":2,"answer_text":"It may not be drawn to scale and cannot establish every required relationship","explanation":"Proof depends on stated or justified facts."},{"id":"geo-d-07","unit":1,"skill":"Segments, Rays, Angles & Notation","prompt":"Point A is at 3 and point B is at 18 on a number line. Find AB.","options":["28","A straight angle","46","15"],"answer":3,"answer_text":"15","explanation":"Distance is |18−3|=15."},{"id":"geo-d-08","unit":1,"skill":"Segments, Rays, Angles & Notation","prompt":"Find the midpoint of A(-1,-2) and B(3,7).","options":["46","(1,2.5)","28","A straight angle"],"answer":1,"answer_text":"(1,2.5)","explanation":"Average the x-coordinates and the y-coordinates separately."},{"id":"geo-d-09","unit":1,"skill":"Segments, Rays, Angles & Notation","prompt":"Point M lies between A and B. If AM=18 and MB=28, find AB.","options":["A straight angle","A postulate is accepted without proof; a theorem is proven","46","28"],"answer":2,"answer_text":"46","explanation":"Use segment addition: AB=AM+MB."},{"id":"geo-d-10","unit":1,"skill":"Segments, Rays, Angles & Notation","prompt":"Write the correct notation for the ray that starts at A and passes through B.","options":["A straight angle","ray AB","46","28"],"answer":1,"answer_text":"ray AB","explanation":"The endpoint letter is written first."},{"id":"geo-d-11","unit":1,"skill":"Segments, Rays, Angles & Notation","prompt":"Explain why the length of segment AB is written without a bar, while the segment itself is written with a bar.","options":["A straight angle","AB is a number; segment AB is a geometric set","28","46"],"answer":1,"answer_text":"AB is a number; segment AB is a geometric set","explanation":"Notation distinguishes the object from its measure."},{"id":"geo-d-12","unit":1,"skill":"Segments, Rays, Angles & Notation","prompt":"A point partitions a 30-unit segment in the ratio 2:3. Find the two part lengths.","options":["28","A straight angle","12 and 18","46"],"answer":2,"answer_text":"12 and 18","explanation":"There are 5 ratio parts; each is 6 units."},{"id":"geo-d-13","unit":3,"skill":"Triangle Classification & Angle Relationships","prompt":"A triangle has angles 60° and 75°. Find the third angle.","options":["45","0<x<22","∠E","SAS"],"answer":0,"answer_text":"45","explanation":"Triangle angles sum to 180°."},{"id":"geo-d-14","unit":3,"skill":"Triangle Classification & Angle Relationships","prompt":"Two sides are 11 and 11. State the integer range for the third side x.","options":["0<x<22","∠E","SAS","45"],"answer":0,"answer_text":"0<x<22","explanation":"Use the triangle inequality and the difference inequality."},{"id":"geo-d-15","unit":3,"skill":"Triangle Classification & Angle Relationships","prompt":"Which congruence theorem uses two sides and the included angle?","options":["45","SAS","0<x<22","∠E"],"answer":1,"answer_text":"SAS","explanation":"The angle must be between the two known sides."},{"id":"geo-d-16","unit":3,"skill":"Triangle Classification & Angle Relationships","prompt":"After proving ΔABC≅ΔDEF, which angle corresponds to ∠B?","options":["0<x<22","∠E","45","SAS"],"answer":1,"answer_text":"∠E","explanation":"The order of vertices determines correspondence."},{"id":"geo-d-17","unit":3,"skill":"Triangle Classification & Angle Relationships","prompt":"Where do the perpendicular bisectors of a triangle meet?","options":["SAS","0<x<22","45","Circumcenter"],"answer":3,"answer_text":"Circumcenter","explanation":"It is equidistant from all three vertices."},{"id":"geo-d-18","unit":3,"skill":"Triangle Classification & Angle Relationships","prompt":"Why does AAA not prove triangle congruence?","options":["SAS","45","0<x<22","It fixes shape but not size"],"answer":3,"answer_text":"It fixes shape but not size","explanation":"AAA establishes similarity."},{"id":"geo-d-19","unit":3,"skill":"SSS and SAS Congruence","prompt":"A triangle has angles 70° and 69°. Find the third angle.","options":["41","SAS","45","0<x<22"],"answer":0,"answer_text":"41","explanation":"Triangle angles sum to 180°."},{"id":"geo-d-20","unit":3,"skill":"SSS and SAS Congruence","prompt":"Two sides are 10 and 11. State the integer range for the third side x.","options":["SAS","1<x<21","45","0<x<22"],"answer":1,"answer_text":"1<x<21","explanation":"Use the triangle inequality and the difference inequality."},{"id":"geo-d-21","unit":3,"skill":"SSS and SAS Congruence","prompt":"Which congruence theorem uses two sides and the included angle?","options":["SAS","45","0<x<22","∠E"],"answer":0,"answer_text":"SAS","explanation":"The angle must be between the two known sides."},{"id":"geo-d-22","unit":3,"skill":"SSS and SAS Congruence","prompt":"After proving ΔABC≅ΔDEF, which angle corresponds to ∠B?","options":["∠E","45","SAS","0<x<22"],"answer":0,"answer_text":"∠E","explanation":"The order of vertices determines correspondence."},{"id":"geo-d-23","unit":3,"skill":"SSS and SAS Congruence","prompt":"Where do the perpendicular bisectors of a triangle meet?","options":["SAS","Circumcenter","0<x<22","45"],"answer":1,"answer_text":"Circumcenter","explanation":"It is equidistant from all three vertices."},{"id":"geo-d-24","unit":3,"skill":"SSS and SAS Congruence","prompt":"Why does AAA not prove triangle congruence?","options":["SAS","45","It fixes shape but not size","0<x<22"],"answer":2,"answer_text":"It fixes shape but not size","explanation":"AAA establishes similarity."},{"id":"geo-d-25","unit":4,"skill":"Parallel Lines Cut by a Transversal","prompt":"Find the slope through A(-2,-4) and B(5,5).","options":["(1.5,0.5)","1.29","−4/3","They are congruent"],"answer":1,"answer_text":"1.29","explanation":"m=(5−(-4))/(5−(-2))=1.29."},{"id":"geo-d-26","unit":4,"skill":"Parallel Lines Cut by a Transversal","prompt":"Find the midpoint of A(-2,-4) and B(5,5).","options":["−4/3","(1.5,0.5)","1.29","They are congruent"],"answer":1,"answer_text":"(1.5,0.5)","explanation":"Average corresponding coordinates."},{"id":"geo-d-27","unit":4,"skill":"Parallel Lines Cut by a Transversal","prompt":"If one nonvertical line has slope 3/4, what is the slope of a perpendicular line?","options":["They are congruent","(1.5,0.5)","−4/3","1.29"],"answer":2,"answer_text":"−4/3","explanation":"Perpendicular nonvertical slopes are negative reciprocals."},{"id":"geo-d-28","unit":4,"skill":"Parallel Lines Cut by a Transversal","prompt":"What angle relationship is formed by alternate interior angles when lines are parallel?","options":["They are congruent","1.29","(1.5,0.5)","−4/3"],"answer":0,"answer_text":"They are congruent","explanation":"This follows from the parallel-lines theorem."},{"id":"geo-d-29","unit":4,"skill":"Parallel Lines Cut by a Transversal","prompt":"What must be shown with slopes to prove a quadrilateral is a parallelogram?","options":["−4/3","Both pairs of opposite sides have equal slopes","(1.5,0.5)","1.29"],"answer":1,"answer_text":"Both pairs of opposite sides have equal slopes","explanation":"Equal slopes establish parallel opposite sides."},{"id":"geo-d-30","unit":4,"skill":"Parallel Lines Cut by a Transversal","prompt":"Write an equation of the horizontal line through (4,−3).","options":["y=−3","−4/3","(1.5,0.5)","1.29"],"answer":0,"answer_text":"y=−3","explanation":"All points on a horizontal line share one y-coordinate."},{"id":"geo-d-31","unit":4,"skill":"Proving Lines Parallel from Angle Relationships","prompt":"Find the slope through A(-2,-4) and B(7,8).","options":["(1.5,0.5)","1.33","−4/3","1.29"],"answer":1,"answer_text":"1.33","explanation":"m=(8−(-4))/(7−(-2))=1.33."},{"id":"geo-d-32","unit":4,"skill":"Proving Lines Parallel from Angle Relationships","prompt":"Find the midpoint of A(-2,-4) and B(7,8).","options":["−4/3","1.29","(1.5,0.5)","(2.5,2)"],"answer":3,"answer_text":"(2.5,2)","explanation":"Average corresponding coordinates."},{"id":"geo-d-33","unit":4,"skill":"Proving Lines Parallel from Angle Relationships","prompt":"If one nonvertical line has slope 3/4, what is the slope of a perpendicular line?","options":["1.29","(1.5,0.5)","−4/3","They are congruent"],"answer":2,"answer_text":"−4/3","explanation":"Perpendicular nonvertical slopes are negative reciprocals."},{"id":"geo-d-34","unit":4,"skill":"Proving Lines Parallel from Angle Relationships","prompt":"What angle relationship is formed by alternate interior angles when lines are parallel?","options":["They are congruent","(1.5,0.5)","−4/3","1.29"],"answer":0,"answer_text":"They are congruent","explanation":"This follows from the parallel-lines theorem."},{"id":"geo-d-35","unit":4,"skill":"Proving Lines Parallel from Angle Relationships","prompt":"What must be shown with slopes to prove a quadrilateral is a parallelogram?","options":["(1.5,0.5)","−4/3","1.29","Both pairs of opposite sides have equal slopes"],"answer":3,"answer_text":"Both pairs of opposite sides have equal slopes","explanation":"Equal slopes establish parallel opposite sides."},{"id":"geo-d-36","unit":4,"skill":"Proving Lines Parallel from Angle Relationships","prompt":"Write an equation of the horizontal line through (4,−3).","options":["y=−3","−4/3","(1.5,0.5)","1.29"],"answer":0,"answer_text":"y=−3","explanation":"All points on a horizontal line share one y-coordinate."},{"id":"geo-d-37","unit":5,"skill":"Dilations from a Center","prompt":"A dilation has scale factor 2.5. A preimage side is 9. Find the image side.","options":["22.5","12.6","It preserves angle measure","Two pairs of congruent angles (AA)"],"answer":0,"answer_text":"22.5","explanation":"Multiply by the scale factor: 9·2.5."},{"id":"geo-d-38","unit":5,"skill":"Dilations from a Center","prompt":"Triangles are similar. A side 5 corresponds to 7; a side 9 corresponds to x. Find x.","options":["22.5","It preserves angle measure","12.6","Two pairs of congruent angles (AA)"],"answer":2,"answer_text":"12.6","explanation":"Use 5/7=9/x."},{"id":"geo-d-39","unit":5,"skill":"Dilations from a Center","prompt":"Which angle evidence alone is sufficient for triangle similarity?","options":["Two pairs of congruent angles (AA)","It preserves angle measure","12.6","22.5"],"answer":0,"answer_text":"Two pairs of congruent angles (AA)","explanation":"The third angle is then congruent automatically."},{"id":"geo-d-40","unit":5,"skill":"Dilations from a Center","prompt":"How does a dilation with scale factor 1/2 affect angle measure?","options":["It preserves angle measure","Two pairs of congruent angles (AA)","22.5","12.6"],"answer":0,"answer_text":"It preserves angle measure","explanation":"Dilations change lengths proportionally but preserve angles."}];